import React, { useEffect, useState, useRef, useCallback } from "react";
import io from "socket.io-client";
import { AuthProvider } from "./Context/AuthContext";
import CanvasBoard from "./components/CanvasBoard";
import ToolBar from "./components/ToolBar";
import UserList from "./components/UserList";
import LoginForm from "./components/LoginForm";
import CursorOverlay from "./components/CursorOverlay";

const socket = io("http://localhost:5000");

function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [user, setUser] = useState(null);
  const [users, setUsers] = useState([]);
  const [cursors, setCursors] = useState({});
  const [isDark, setIsDark] = useState(true);

  useEffect(() => {
    // Apply dark mode class to html element
    document.documentElement.classList.toggle("dark", isDark);
  }, [isDark]);

  useEffect(() => {
    socket.on("userList", (userList) => {
      setUsers(userList);
    });

    socket.on("cursor-update", ({ userId, x, y, name, color }) => {
      setCursors((prev) => ({ ...prev, [userId]: { x, y, name, color } }));
    });

    // Remove cursor when user leaves
    socket.on("userLeft", ({ userId }) => {
      setCursors((prev) => {
        const next = { ...prev };
        delete next[userId];
        return next;
      });
    });

    return () => {
      socket.off("userList");
      socket.off("cursor-update");
      socket.off("userLeft");
    };
  }, []);

  const handleLogin = (userData) => {
    setUser(userData);
    setIsLoggedIn(true);
    socket.emit("userJoined", userData);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setUser(null);
    socket.disconnect();
    socket.connect();
  };

  if (!isLoggedIn) {
    return (
      <AuthProvider>
        <div className={isDark ? "dark" : ""}>
          <div className="min-h-screen bg-zinc-950 flex items-center justify-center">
            <LoginForm onLogin={handleLogin} />
          </div>
        </div>
      </AuthProvider>
    );
  }

  return (
    <AuthProvider>
      <div className="h-screen flex flex-col bg-zinc-950 text-white">

        {/* Header */}
        <div className="flex items-center justify-between px-6 py-3 bg-zinc-900 border-b border-zinc-800 shrink-0">

          {/* Left: logo + title */}
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 bg-indigo-600 rounded-xl flex items-center justify-center shadow">
              <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2}
                  d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" />
              </svg>
            </div>
            <div>
              <h1 className="text-base font-semibold text-white leading-tight">Collaborative Whiteboard</h1>
              <p className="text-xs text-zinc-500">Real-time drawing collaboration</p>
            </div>
          </div>

          {/* Right: dark mode toggle + user badge + logout */}
          <div className="flex items-center gap-3">

            {/* Dark mode toggle */}
            <button
              onClick={() => setIsDark((v) => !v)}
              className="w-9 h-9 rounded-xl bg-zinc-800 hover:bg-zinc-700 flex items-center justify-center text-zinc-400 hover:text-white transition-colors"
              title="Toggle theme"
            >
              {isDark ? (
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2}
                    d="M12 3v1m0 16v1m8.66-9h-1M4.34 12h-1m15.07-6.07l-.71.71M6.34 17.66l-.71.71M17.66 17.66l-.71-.71M6.34 6.34l-.71-.71M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
                </svg>
              ) : (
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2}
                    d="M21 12.79A9 9 0 1111.21 3 7 7 0 0021 12.79z" />
                </svg>
              )}
            </button>

            {/* User badge */}
            <div className="flex items-center gap-2 bg-zinc-800 rounded-xl px-3 py-1.5 text-sm">
              <span className="text-zinc-300 font-medium">{user?.username}</span>
              <span className="px-1.5 py-0.5 bg-zinc-700 rounded-lg text-xs text-zinc-400">
                {user?.role === "admin" && "👑 "}
                {user?.role === "editor" && "✏️ "}
                {user?.role === "viewer" && "👁️ "}
                {user?.role}
              </span>
            </div>

            {/* Logout */}
            <button
              onClick={handleLogout}
              className="flex items-center gap-2 px-4 py-1.5 bg-red-500/20 hover:bg-red-500/30 text-red-400 hover:text-red-300 border border-red-500/30 rounded-xl text-sm transition-colors"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2}
                  d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
              </svg>
              Logout
            </button>
          </div>
        </div>

        {/* Toolbar */}
        <ToolBar socket={socket} />

        {/* Main area */}
        <div className="flex-1 flex overflow-hidden">

          {/* Canvas + cursor overlay wrapper */}
          <div className="flex-1 relative">
            <CanvasBoard socket={socket} user={user} />
            <CursorOverlay cursors={cursors} />
          </div>

          {/* User list sidebar */}
          <UserList users={users} />
        </div>

      </div>
    </AuthProvider>
  );
}

export default App;
